const clean=s=>s.replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\\s+/g,' ').trim();
const qs=[
  ['简历优化-亏/难做','简历优化 不赚钱 亏'],
  ['简历优化-竞争饱和','简历修改 太卷了 没单'],
  ['论文查重-竞争','论文降重 利润 竞争'],
  ['大学生副业-打假','大学生副业 打假 割韭菜'],
];
for(const [tag,q] of qs){
  const h=await curl('https://weixin.sogou.com/weixin?type=2&query='+encodeURIComponent(q));
  const body=clean(h.replace(/<script[\\s\\S]*?<\\/script>/gi,' '));
  // 提取「以下内容来自微信公众平台」之后的部分
  const i=body.indexOf('以下内容来自微信公众平台');
  const content=i>0?body.slice(i,i+1500):body.slice(0,1500);
  console.log('=== '+tag+' bytes='+h.length);
  console.log(content.slice(0,900));
  console.log('');
  await new Promise(r=>setTimeout(r,5000));
}
`;
